designs.autoRevert:
{
  "mechanism": "Server-authoritative: expiresAt timestamp checked on every /sports/board/:id call",
  "serverSide": "If (expiresAt <= now()) getBoardFresh() returns activeScene=null; next poll clears the scene",
  "clientSide": "SceneAutoRevertChip polls every 100ms, calls ctl.sceneClear.mutate() on expiry (courtesy clear; server enforces)",
  "robustness": "Operator closes laptop + board stops polling for 24h? Scene's expiresAt is permanent; next board load (days later) sees it expired and reverts. Cannot get stranded."
}

